final class PhotoCell: UICollectionViewCell {
  let imageView = UIImageView()
  private var loadTask: Task<Void, Never>?
  private var showingID: Photo.ID?

  // Reuse hands back the object, not a blank slate: whatever the last row left
  // here is still on screen until something overwrites it.
  override func prepareForReuse() {
    super.prepareForReuse()
    loadTask?.cancel()        // stop work that would land in the wrong row
    loadTask = nil
    imageView.image = nil     // clear what an async result writes into
    showingID = nil
  }

  // WRONG: nothing cancels, and a late result paints the cell it captured,
  // whichever row that cell is showing by then.
  func configureNaively(with photo: Photo) {
    Task { self.imageView.image = await Loader.image(photo.url) }
  }

  // RIGHT: cancel on reuse, and re-check identity when the result comes back.
  func configure(with photo: Photo) {
    showingID = photo.id
    imageView.image = photo.blurHashPlaceholder
    loadTask = Task { [weak self] in
      let image = await Loader.image(photo.url)
      guard let self, !Task.isCancelled, self.showingID == photo.id else { return }
      self.imageView.image = image
    }
  }
}

// The modern dequeue path runs the registration handler on every reuse, so
// configure() above is called for each cell that scrolls back into view.
let registration = UICollectionView.CellRegistration<PhotoCell, Photo> { cell, _, photo in
  cell.configure(with: photo)
}

// item -> group -> section -> layout. A group is itself an item, so groups nest.
let item = NSCollectionLayoutItem(layoutSize: NSCollectionLayoutSize(
  widthDimension: .fractionalWidth(1.0),    // 1.0 of the GROUP, not of the screen
  heightDimension: .fractionalHeight(1.0)))
item.contentInsets = .init(top: 6, leading: 6, bottom: 6, trailing: 6)  // gutters live here

// WRONG: two halves already fill the group, so the spacing pushes column two out.
let halfItem = NSCollectionLayoutItem(layoutSize: .init(
  widthDimension: .fractionalWidth(0.5), heightDimension: .fractionalHeight(1.0)))
let broken = NSCollectionLayoutGroup.horizontal(
  layoutSize: .init(widthDimension: .fractionalWidth(1.0), heightDimension: .absolute(160)),
  repeatingSubitem: halfItem, count: 2)
broken.interItemSpacing = .fixed(12)

// RIGHT: keep the fractions summing to 1.0 and take spacing out of the insets.
// repeatingSubitem:count: replaced subitem:count:, deprecated in iOS 16.
let row = NSCollectionLayoutGroup.horizontal(
  layoutSize: .init(widthDimension: .fractionalWidth(1.0),
                    heightDimension: .estimated(160)),   // self-sizing starting guess
  repeatingSubitem: item, count: 2)

let section = NSCollectionLayoutSection(group: row)
section.contentInsets = .init(top: 12, leading: 12, bottom: 12, trailing: 12)
section.interGroupSpacing = 8

// The provider form sees the environment, so the column count can follow the width.
let layout = UICollectionViewCompositionalLayout { _, environment in
  let columns = environment.container.effectiveContentSize.width > 700 ? 4 : 2
  let wide = NSCollectionLayoutGroup.horizontal(
    layoutSize: .init(widthDimension: .fractionalWidth(1.0), heightDimension: .estimated(160)),
    repeatingSubitem: item, count: columns)
  return NSCollectionLayoutSection(group: wide)
}

func carouselSection() -> NSCollectionLayoutSection {
  let item = NSCollectionLayoutItem(layoutSize: .init(
    widthDimension: .fractionalWidth(1.0), heightDimension: .fractionalHeight(1.0)))

  // 0.75 wide so the neighbouring cards peek in on both sides.
  let group = NSCollectionLayoutGroup.horizontal(
    layoutSize: .init(widthDimension: .fractionalWidth(0.75), heightDimension: .absolute(220)),
    subitems: [item])
  group.contentInsets = .init(top: 0, leading: 8, bottom: 0, trailing: 8)

  let section = NSCollectionLayoutSection(group: group)
  section.orthogonalScrollingBehavior = .groupPagingCentered  // its own private scroll view
  section.orthogonalScrollingProperties.decelerationRate = .fast   // iOS 17+

  // Fires on every offset change of THAT scroll view, not the collection view's.
  // transform / alpha / zIndex apply straight away, with no layout invalidation.
  section.visibleItemsInvalidationHandler = { visibleItems, offset, environment in
    let centreX = offset.x + environment.container.contentSize.width / 2
    for item in visibleItems where item.representedElementCategory == .cell {
      let distance = abs(item.frame.midX - centreX)
      let ratio = distance / environment.container.contentSize.width
      let scale = max(1 - ratio, 0.84)
      item.transform = CGAffineTransform(scaleX: scale, y: scale)
      item.alpha = max(scale, 0.6)
    }
  }
  return section
}

// The layout retains this closure and the collection view retains the layout, so a
// handler that needs the view controller must not capture it strongly.
section.visibleItemsInvalidationHandler = { [weak self] items, offset, _ in
  self?.pageControl.currentPage = Int(round(offset.x / max(items.first?.frame.width ?? 1, 1)))
  // Never call invalidateLayout() here — it re-enters this handler.
}

let badgeKind = "badge", backgroundKind = "section-background"

// Anchored supplementary: edges plus a fractional offset put it outside the corner.
let badge = NSCollectionLayoutSupplementaryItem(
  layoutSize: .init(widthDimension: .absolute(20), heightDimension: .absolute(20)),
  elementKind: badgeKind,
  containerAnchor: NSCollectionLayoutAnchor(edges: [.top, .trailing],
                                            fractionalOffset: CGPoint(x: 0.3, y: -0.3)))

let item = NSCollectionLayoutItem(
  layoutSize: .init(widthDimension: .fractionalWidth(1.0), heightDimension: .fractionalHeight(1.0)),
  supplementaryItems: [badge])
let section = NSCollectionLayoutSection(group: .horizontal(
  layoutSize: .init(widthDimension: .fractionalWidth(1.0), heightDimension: .absolute(120)),
  repeatingSubitem: item, count: 3))

let header = NSCollectionLayoutBoundarySupplementaryItem(
  layoutSize: .init(widthDimension: .fractionalWidth(1.0), heightDimension: .estimated(44)),
  elementKind: UICollectionView.elementKindSectionHeader, alignment: .top)
header.pinToVisibleBounds = true   // sticky while the section scrolls
section.boundarySupplementaryItems = [header]

let card = NSCollectionLayoutDecorationItem.background(elementKind: backgroundKind)
card.contentInsets = .init(top: 8, leading: 16, bottom: 8, trailing: 16)
section.decorationItems = [card]

let layout = UICollectionViewCompositionalLayout(section: section)
// The data source never sees a decoration view: this is the ONLY place its class
// is named, and omitting it raises on first display.
layout.register(CardBackgroundView.self, forDecorationViewOfKind: backgroundKind)

// Supplementaries DO reach the data source, and nil for a declared kind is a crash.
dataSource.supplementaryViewProvider = { view, kind, path in
  kind == UICollectionView.elementKindSectionHeader
    ? view.dequeueConfiguredReusableSupplementary(using: headerReg, for: path)
    : view.dequeueConfiguredReusableSupplementary(using: badgeReg, for: path)
}

private func makeLayout() -> UICollectionViewLayout {
  var config = UICollectionLayoutListConfiguration(appearance: .insetGrouped)
  config.headerMode = .supplementary
  config.separatorConfiguration.color = .separator

  // Stored on the layout for the screen's lifetime — a strong self leaks the VC.
  config.trailingSwipeActionsConfigurationProvider = { [weak self] indexPath in
    // The IndexPath is stale the moment any snapshot lands. Resolve it to an
    // identifier now, and never carry the index path into the handler.
    guard let self, let id = self.dataSource.itemIdentifier(for: indexPath) else { return nil }
    let delete = UIContextualAction(style: .destructive, title: "Delete") { _, _, done in
      var snapshot = self.dataSource.snapshot()
      snapshot.deleteItems([id])        // the row does not vanish by itself
      self.dataSource.apply(snapshot, animatingDifferences: true)
      done(true)
    }
    return UISwipeActionsConfiguration(actions: [delete])
  }
  return UICollectionViewCompositionalLayout.list(using: config)
}

// One list section among grid sections — the reason lists live in collection views.
let mixed = UICollectionViewCompositionalLayout { index, environment in
  guard index == 0 else { return gridSection() }
  return NSCollectionLayoutSection.list(
    using: UICollectionLayoutListConfiguration(appearance: .insetGrouped),
    layoutEnvironment: environment)
}

let rowRegistration = UICollectionView.CellRegistration<UICollectionViewListCell, Todo.ID> {
  cell, _, id in
  var content = cell.defaultContentConfiguration()
  content.text = store[id]?.title
  cell.contentConfiguration = content
  cell.accessories = [.disclosureIndicator(), .reorder()]
}

// Created ONCE. Building a registration inside the cell provider makes a new one
// per dequeue, so nothing is ever reused and scrolling falls apart.
private lazy var rowRegistration =
  UICollectionView.CellRegistration<UICollectionViewListCell, Todo.ID> { [weak self] cell, _, id in
    guard let todo = self?.store[id] else { return }
    // Configurations are values: copy, mutate, assign back. Mutating what you read
    // out of cell.contentConfiguration changes nothing on screen.
    var content = cell.defaultContentConfiguration()
    content.text = todo.title
    content.secondaryText = todo.due.formatted(date: .abbreviated, time: .omitted)
    content.image = UIImage(systemName: todo.isDone ? "checkmark.circle.fill" : "circle")
    cell.contentConfiguration = content

    cell.accessories = [.disclosureIndicator()]
  }

dataSource = UICollectionViewDiffableDataSource<Section, Todo.ID>(collectionView: view) {
  view, indexPath, id in
  view.dequeueConfiguredReusableCell(using: self.rowRegistration, for: indexPath, item: id)
}

// Declarative state: describe the cell for a state, let UIKit pick the moment.
final class PriceCell: UICollectionViewListCell {
  var isFlagged = false { didSet { setNeedsUpdateConfiguration() } }

  override var configurationState: UICellConfigurationState {
    var state = super.configurationState
    state[.flagged] = isFlagged
    return state
  }

  // Called on selection, highlight, disabled, focus and trait changes — which is
  // why colours never get flipped from didSelectItemAt any more.
  override func updateConfiguration(using state: UICellConfigurationState) {
    var content = defaultContentConfiguration().updated(for: state)
    content.textProperties.color = (state[.flagged] as? Bool == true) ? .systemRed : .label
    contentConfiguration = content
  }
}

extension UIConfigurationStateCustomKey {
  static let flagged = UIConfigurationStateCustomKey("com.example.flagged")
}

struct Message: Identifiable, Hashable {
  let id: UUID
  var text: String
  var isRead: Bool
}

// WRONG: the item type is the model, so hashing covers `text`. Edit the text and
// the diff sees a delete plus an insert — the row flies out and back in.
var wrong = NSDiffableDataSourceSnapshot<Section, Message>()

// RIGHT: identity in the snapshot, values in a store the registration reads.
private var store: [Message.ID: Message] = [:]
private var dataSource: UICollectionViewDiffableDataSource<Section, Message.ID>!

func show(_ messages: [Message]) {
  store = Dictionary(uniqueKeysWithValues: messages.map { ($0.id, $0) })
  var snapshot = NSDiffableDataSourceSnapshot<Section, Message.ID>()
  snapshot.appendSections([.inbox])
  snapshot.appendItems(messages.map(\.id), toSection: .inbox)
  dataSource.apply(snapshot, animatingDifferences: true)
}

// A snapshot is a value type: this is a copy, not a live view of the data source.
var next = dataSource.snapshot()
next.deleteItems([id])
dataSource.apply(next)

// A hard reset — the explicit replacement for the old `animatingDifferences: false`
// trick, which since iOS 15 still runs a diff.
dataSource.applySnapshotUsingReloadData(next)

// Off the main queue is allowed, but EVERY apply must use the same queue, first
// one included. Mixing main and background is a race, not a warning.
private let updates = DispatchQueue(label: "inbox.updates")
func ingest(_ page: [Message]) {
  updates.async { [weak self] in
    guard let self else { return }
    var snapshot = self.dataSource.snapshot()
    snapshot.appendItems(page.map(\.id), toSection: .inbox)
    self.dataSource.apply(snapshot, animatingDifferences: true)
  }
}

// Synthesized Hashable covers every stored property, so two rows that look alike
// ARE the same identifier — and an edit to `title` changes the identity outright.
struct Row: Hashable {
  let id: String
  var title: String
  var subtitle: String
}

var snapshot = NSDiffableDataSourceSnapshot<Section, Row>()
snapshot.appendSections([.main])
snapshot.appendItems([Row(id: "a", title: "—", subtitle: ""),
                      Row(id: "b", title: "—", subtitle: "")])
// Fine here, because `id` differs. Drop `id` from the struct and this is the crash.

// Fix: define equality and hashing against the id alone. Declaring them suppresses
// synthesis, so identity stops tracking the display values.
extension Row {
  static func == (lhs: Row, rhs: Row) -> Bool { lhs.id == rhs.id }
  func hash(into hasher: inout Hasher) { hasher.combine(id) }
}

// A cheap guard for anything fed by a server or a paged API.
#if DEBUG
let duplicates = Dictionary(grouping: snapshot.itemIdentifiers, by: \.id)
  .filter { $0.value.count > 1 }.keys
assert(duplicates.isEmpty, "duplicate identifiers: \(Array(duplicates))")
#endif

// The diff matches on identifiers only:
//   in both, different position -> move
//   new only -> insert;  old only -> delete
//   same identifier, same position -> nothing at all
var next = dataSource.snapshot()
next.moveItem(rowC, afterItem: rowA)   // recorded as a move, animated as one
store[rowB.id]?.title = "Renamed"      // invisible to the diff on its own...
next.reconfigureItems([rowB])          // ...until the snapshot says so explicitly
dataSource.apply(next, animatingDifferences: true)

struct Song: Hashable { let id: UUID; var title: String; var isFavourite: Bool }

// The snapshot carries ids only. If it carried Song values, flipping isFavourite
// would change the identifier and every edit would become a delete plus an insert.
private var store: [UUID: Song] = [:]
private var dataSource: UICollectionViewDiffableDataSource<Int, UUID>!

private lazy var registration =
  UICollectionView.CellRegistration<UICollectionViewListCell, UUID> { [weak self] cell, _, id in
    guard let song = self?.store[id] else { return }
    var content = cell.defaultContentConfiguration()
    content.text = song.title
    cell.contentConfiguration = content
    cell.accessories = song.isFavourite ? [.label(text: "★")] : []
  }

func toggleFavourite(_ id: UUID) {
  store[id]?.isFavourite.toggle()

  // WRONG: the cell is torn down and re-dequeued. prepareForReuse runs, the decoded
  // artwork is discarded, and a text field in that row resigns first responder.
  var reloaded = dataSource.snapshot()
  reloaded.reloadItems([id])
  dataSource.apply(reloaded)

  // RIGHT: the same cell instance, the registration handler runs again with new
  // values. No dequeue, no prepareForReuse — animations and focus survive.
  var snapshot = dataSource.snapshot()
  snapshot.reconfigureItems([id])
  dataSource.apply(snapshot, animatingDifferences: true)
}

enum Section { case settings }
struct Row: Hashable { let id: String; let title: String }

private var dataSource: UICollectionViewDiffableDataSource<Section, Row>!

func applySettings(_ groups: [(header: Row, children: [Row])]) {
  // Read the state out before the rebuild discards it — the tree and the
  // expansion live together in the section snapshot, nowhere else.
  let old = dataSource.snapshot(for: .settings)
  let expanded = Set(old.items.filter { old.isExpanded($0) })

  var snapshot = NSDiffableDataSourceSectionSnapshot<Row>()
  for group in groups {
    snapshot.append([group.header])                    // a root
    snapshot.append(group.children, to: group.header)  // its children
    if expanded.contains(group.header) { snapshot.expand([group.header]) }
  }
  dataSource.apply(snapshot, to: .settings, animatingDifferences: true)
}

// The triangle is an accessory, not a gesture recogniser you write.
private let headerRegistration =
  UICollectionView.CellRegistration<UICollectionViewListCell, Row> { cell, _, row in
    var content = cell.defaultContentConfiguration()
    content.text = row.title
    cell.contentConfiguration = content
    cell.accessories = [.outlineDisclosure(options: .init(style: .header))]
  }

func configureHandlers() {
  // Persist here — never in a second isExpanded flag on the model.
  dataSource.sectionSnapshotHandlers.willCollapseItem = { item in
    UserDefaults.standard.set(false, forKey: "expanded.\(item.id)")
  }
  dataSource.sectionSnapshotHandlers.willExpandItem = { item in
    UserDefaults.standard.set(true, forKey: "expanded.\(item.id)")
  }
}

// A section that measures its cells: estimated group height, item fills the group.
func makeLayout() -> UICollectionViewCompositionalLayout {
  let item = NSCollectionLayoutItem(layoutSize: .init(widthDimension: .fractionalWidth(1),
                                                      heightDimension: .fractionalHeight(1)))
  let group = NSCollectionLayoutGroup.vertical(
    layoutSize: .init(widthDimension: .fractionalWidth(1),
                      heightDimension: .estimated(120)),  // closer to the truth, smaller the jump
    subitems: [item])
  return UICollectionViewCompositionalLayout(section: NSCollectionLayoutSection(group: group))
}

final class PostCell: UICollectionViewCell {
  let body = UILabel()

  override init(frame: CGRect) {
    super.init(frame: frame)
    body.numberOfLines = 0
    body.translatesAutoresizingMaskIntoConstraints = false
    contentView.addSubview(body)
    NSLayoutConstraint.activate([
      body.topAnchor.constraint(equalTo: contentView.topAnchor, constant: 12),
      body.leadingAnchor.constraint(equalTo: contentView.leadingAnchor, constant: 16),
      // Without the trailing constraint the label measures as one endless line.
      body.trailingAnchor.constraint(equalTo: contentView.trailingAnchor, constant: -16),
      // Without the bottom constraint the chain is broken and the cell keeps its estimate.
      body.bottomAnchor.constraint(equalTo: contentView.bottomAnchor, constant: -12),
    ])
  }
  required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

  // Width is required, height is free — that is the whole point of the override.
  override func preferredLayoutAttributesFitting(
    _ attributes: UICollectionViewLayoutAttributes) -> UICollectionViewLayoutAttributes {
    attributes.size = contentView.systemLayoutSizeFitting(
      CGSize(width: attributes.size.width, height: 0),
      withHorizontalFittingPriority: .required,
      verticalFittingPriority: .fittingSizeLevel)
    return attributes
  }
}

collectionView.selfSizingInvalidation = .enabledIncludingConstraints  // iOS 16+

@MainActor
final class FeedViewController: UIViewController {
  private var dataSource: UICollectionViewDiffableDataSource<Int, Post.ID>!
  private var cache: [Post.ID: UIImage] = [:]
  // Keyed by the stable id. An IndexPath key cancels the wrong download the
  // first time a snapshot inserts or reorders anything.
  private var tasks: [Post.ID: Task<Void, Never>] = [:]

  func startLoad(_ id: Post.ID) {
    guard tasks[id] == nil, cache[id] == nil else { return }
    tasks[id] = Task { [weak self] in
      defer { self?.tasks[id] = nil }
      guard let url = self?.imageURL(for: id),
            let (data, _) = try? await URLSession.shared.data(from: url) else { return }
      guard !Task.isCancelled else { return }   // cancellation is cooperative
      self?.cache[id] = await downsample(data, to: CGSize(width: 320, height: 320))
    }
  }

  func cancelLoad(_ id: Post.ID) { tasks.removeValue(forKey: id)?.cancel() }
}

extension FeedViewController: UICollectionViewDataSourcePrefetching {
  func collectionView(_ cv: UICollectionView, prefetchItemsAt indexPaths: [IndexPath]) {
    indexPaths.compactMap { dataSource.itemIdentifier(for: $0) }.forEach(startLoad)
  }

  // The half everyone forgets: a fling otherwise queues a hundred downloads
  // that outlive the cells that asked for them.
  func collectionView(_ cv: UICollectionView, cancelPrefetchingForItemsAt indexPaths: [IndexPath]) {
    indexPaths.compactMap { dataSource.itemIdentifier(for: $0) }.forEach(cancelLoad)
  }
}

// Prefetch never runs for the first screenful, so the cell still loads on demand.
let registration = UICollectionView.CellRegistration<PostCell, Post.ID> { [weak self] cell, _, id in
  cell.image = self?.cache[id]
  self?.startLoad(id)
}

// The snapshot's item type is the id; the model is an order array plus a store.
private var order: [Item.ID] = []
private var store: [Item.ID: Item] = [:]

func configureReordering() {
  dataSource.reorderingHandlers.canReorderItem = { [weak self] id in
    self?.store[id]?.isPinned == false
  }

  dataSource.reorderingHandlers.didReorder = { [weak self] transaction in
    guard let self, let reordered = self.order.applying(transaction.difference) else { return }
    // Without this the drag is purely visual, and the next apply() from the
    // model drops the row back where it was.
    self.order = reordered
    self.persist(reordered)
  }
}

// A list cell offers a grip only if it carries the accessory.
private let registration =
  UICollectionView.CellRegistration<UICollectionViewListCell, Item.ID> { [weak self] cell, _, id in
    var content = cell.defaultContentConfiguration()
    content.text = self?.store[id]?.title
    cell.contentConfiguration = content
    cell.accessories = [.reorder(displayed: .always)]
  }

// Live updates have to wait for the drag to finish, or the drop snaps back.
private var pending: [Item.ID]?

func feedDidUpdate(_ latest: [Item.ID]) {
  guard !collectionView.hasActiveDrag else { pending = latest; return }
  order = latest
  applySnapshot(order)
}

func collectionView(_ cv: UICollectionView, dragSessionDidEnd session: UIDragSession) {
  guard let latest = pending else { return }
  pending = nil
  order = latest
  applySnapshot(latest)
}

final class StaggeredLayout: UICollectionViewLayout {
  var itemHeights: [CGFloat] = []
  private let columns = 2
  private var cache: [UICollectionViewLayoutAttributes] = []   // sorted by frame.minY
  private var contentHeight: CGFloat = 0
  private var tallest: CGFloat = 0
  private var cachedWidth: CGFloat = 0

  override var collectionViewContentSize: CGSize { .init(width: cachedWidth, height: contentHeight) }

  // Compute here — once per invalidation, never per frame.
  override func prepare() {
    guard let cv = collectionView else { return }
    cache.removeAll(); contentHeight = 0; tallest = 0
    cachedWidth = cv.bounds.width
    let width = cachedWidth / CGFloat(columns)
    var columnY = [CGFloat](repeating: 0, count: columns)

    for item in 0..<cv.numberOfItems(inSection: 0) {
      let column = columnY.enumerated().min { $0.element < $1.element }!.offset
      let height = itemHeights[item]
      let attrs = UICollectionViewLayoutAttributes(forCellWith: IndexPath(item: item, section: 0))
      attrs.frame = CGRect(x: CGFloat(column) * width, y: columnY[column],
                           width: width, height: height)
      cache.append(attrs)
      columnY[column] = attrs.frame.maxY
      contentHeight = max(contentHeight, attrs.frame.maxY)
      tallest = max(tallest, height)
    }
    cache.sort { $0.frame.minY < $1.frame.minY }
  }

  // Look up, don't compute: a linear scan here is what makes scrolling crawl.
  override func layoutAttributesForElements(in rect: CGRect) -> [UICollectionViewLayoutAttributes]? {
    var lo = 0, hi = cache.count
    while lo < hi {                                  // binary-search the first candidate
      let mid = (lo + hi) / 2
      if cache[mid].frame.minY < rect.minY - tallest { lo = mid + 1 } else { hi = mid }
    }
    var found: [UICollectionViewLayoutAttributes] = []
    while lo < cache.count, cache[lo].frame.minY <= rect.maxY {
      if cache[lo].frame.intersects(rect) { found.append(cache[lo]) }
      lo += 1
    }
    return found   // supplementary and decoration attributes belong in here too
  }

  // Returning true for every bounds change re-runs prepare() on every scroll frame.
  override func shouldInvalidateLayout(forBoundsChange newBounds: CGRect) -> Bool {
    newBounds.width != cachedWidth
  }
}

// One serial queue owns the model, the snapshot build and the apply. Mixing this
// with a main-queue apply is what produces the duplicate-identifier crash that
// only ever reproduces under load.
private let updates = DispatchQueue(label: "feed.updates")
private var store = MessageStore()
private var buffered: [Message] = []
private var flushScheduled = false

func received(_ batch: [Message]) {
  updates.async { [self] in
    buffered.append(contentsOf: batch)
    guard !flushScheduled else { return }   // coalesce: one apply per window
    flushScheduled = true
    updates.asyncAfter(deadline: .now() + 0.1) { [self] in
      flushScheduled = false
      flush()
    }
  }
}

private func flush() {
  store.merge(buffered)
  buffered = []

  var snapshot = NSDiffableDataSourceSnapshot<Int, Message.ID>()
  snapshot.appendSections([0])
  // UUIDs, not twenty-field structs: the identifier's Hashable conformance is
  // the per-item cost of every diff.
  snapshot.appendItems(store.sortedIDs)
  dataSource.apply(snapshot, animatingDifferences: true)   // same queue, every time
}

// First load or a new search term: there is nothing meaningful to diff, so don't.
func replaceAll(_ messages: [Message]) {
  updates.async { [self] in
    store.reset(messages)
    var snapshot = NSDiffableDataSourceSnapshot<Int, Message.ID>()
    snapshot.appendSections([0])
    snapshot.appendItems(store.sortedIDs)
    dataSource.applySnapshotUsingReloadData(snapshot)
  }
}

// STEP 1 — rows become data, and this function is the thing you actually test.
enum Row: Hashable { case header(String), toggle(SettingKey), destructive }

func items(for state: SettingsState) -> [Row] {
  var rows: [Row] = [.header(state.accountName)]
  rows += state.visibleKeys.map(Row.toggle)
  if state.canDeleteAccount { rows.append(.destructive) }
  return rows
}

// BEFORE — height, section title and swipe actions are three delegate methods,
// and every one of them keys off a row number.
func tableView(_ t: UITableView, heightForRowAt ip: IndexPath) -> CGFloat { ip.row == 0 ? 88 : 44 }
func tableView(_ t: UITableView, titleForHeaderInSection s: Int) -> String? { sections[s].title }
func tableView(_ t: UITableView,
               trailingSwipeActionsConfigurationForRowAt ip: IndexPath) -> UISwipeActionsConfiguration? {
  ip.row == 0 ? nil : UISwipeActionsConfiguration(actions: [resetAction(sections[ip.section].keys[ip.row])])
}

// AFTER — heights are gone into the layout, the header is configuration, and the
// swipe action resolves from the item identifier rather than from a row number.
func makeLayout() -> UICollectionViewCompositionalLayout {
  var config = UICollectionLayoutListConfiguration(appearance: .insetGrouped)
  config.headerMode = .supplementary
  config.trailingSwipeActionsConfigurationProvider = { [weak self] indexPath in
    guard let self, let row = self.dataSource.itemIdentifier(for: indexPath),
          case .toggle(let key) = row else { return nil }
    return UISwipeActionsConfiguration(actions: [self.resetAction(key)])
  }
  return UICollectionViewCompositionalLayout.list(using: config)
}

// The one delegate method that survives — under a different name, and reading
// the identifier instead of trusting the index path.
func collectionView(_ cv: UICollectionView, didSelectItemAt indexPath: IndexPath) {
  cv.deselectItem(at: indexPath, animated: true)
  guard let row = dataSource.itemIdentifier(for: indexPath) else { return }
  handle(row)
}
